import Foundation
import Security
import BackgroundTasks
// The `SyncCore` module below is generated by:
//   cargo run --bin uniffi-bindgen generate --library <path-to-.dylib> \
//     --language swift --out-dir clients/ios/generated
// then built into an XCFramework:
//   cargo build --target aarch64-apple-ios --release
//   cargo build --target aarch64-apple-ios-sim --release
//   xcodebuild -create-xcframework \
//     -library target/aarch64-apple-ios/release/libsync_core.a \
//     -library target/aarch64-apple-ios-sim/release/libsync_core.a \
//     -output SyncCore.xcframework
import SyncCore

/// Thin, idiomatic Swift wrapper. Core calls are synchronous/blocking on the
/// Rust side, so we dispatch to a background queue here — this file is the
/// only place iOS-specific concurrency handling lives.
final class SyncEngine {
    private let handle: SyncEngineHandle
    private let queue = DispatchQueue(label: "sync.engine", qos: .utility)

    init(serverUrl: String, authToken: String, deviceId: String, userId: String) throws {
        let dbPath = FileManager.default
            .urls(for: .applicationSupportDirectory, in: .userDomainMask)[0]
            .appendingPathComponent("sync.db").path
        self.handle = try SyncEngineHandle(config: EngineConfigFfi(
            sqlitePath: dbPath,
            dbEncryptionKey: Self.getOrCreateEncryptionKey(),
            serverUrl: serverUrl,
            authToken: authToken,
            deviceId: deviceId,
            userId: userId
        ))
    }

    /// Retrieves this device's local-DB encryption key from the iOS
    /// Keychain, generating one on first run. The key never leaves the
    /// device and is never sent to the server — losing it just means a
    /// fresh local cache gets re-pulled from the server on next sync.
    private static func getOrCreateEncryptionKey() -> String {
        let service = "com.yourapp.sync.dbkey"
        let account = "local-db-key"

        let query: [String: Any] = [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrService as String: service,
            kSecAttrAccount as String: account,
            kSecReturnData as String: true,
        ]
        var item: CFTypeRef?
        if SecItemCopyMatching(query as CFDictionary, &item) == errSecSuccess,
           let data = item as? Data, let existing = String(data: data, encoding: .utf8) {
            return existing
        }

        var randomBytes = [UInt8](repeating: 0, count: 32)
        _ = SecRandomCopyBytes(kSecRandomDefault, randomBytes.count, &randomBytes)
        let newKey = Data(randomBytes).base64EncodedString()

        let addQuery: [String: Any] = [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrService as String: service,
            kSecAttrAccount as String: account,
            kSecValueData as String: Data(newKey.utf8),
            // Available after first unlock, excluded from device backups —
            // appropriate for a locally-derived key tied to this device.
            kSecAttrAccessible as String: kSecAttrAccessibleAfterFirstUnlockThisDeviceOnly,
        ]
        SecItemAdd(addQuery as CFDictionary, nil)
        return newKey
    }

    func upsert(table: String, rowId: String, fields: [String: Any?], isInsert: Bool, completion: @escaping (Result<Void, Error>) -> Void) {
        queue.async {
            do {
                let converted = fields.mapValues { Self.toFieldValue($0) }
                try self.handle.applyLocalChange(table: table, rowId: rowId, op: isInsert ? "insert" : "update", fields: converted)
                DispatchQueue.main.async { completion(.success(())) }
            } catch {
                DispatchQueue.main.async { completion(.failure(error)) }
            }
        }
    }

    func delete(table: String, rowId: String, completion: @escaping (Result<Void, Error>) -> Void) {
        queue.async {
            do {
                try self.handle.applyLocalChange(table: table, rowId: rowId, op: "delete", fields: [:])
                DispatchQueue.main.async { completion(.success(())) }
            } catch {
                DispatchQueue.main.async { completion(.failure(error)) }
            }
        }
    }

    /// Returns the merged row decoded from JSON, or nil if absent/deleted.
    func getRow(table: String, rowId: String, completion: @escaping (Result<[String: Any]?, Error>) -> Void) {
        queue.async {
            do {
                guard let json = try self.handle.getRowJson(table: table, rowId: rowId) else {
                    DispatchQueue.main.async { completion(.success(nil)) }
                    return
                }
                let dict = try JSONSerialization.jsonObject(with: Data(json.utf8)) as? [String: Any]
                DispatchQueue.main.async { completion(.success(dict)) }
            } catch {
                DispatchQueue.main.async { completion(.failure(error)) }
            }
        }
    }

    /// Push local changes, pull remote changes. Call on app foreground,
    /// on BGTaskScheduler background refresh, and after local writes.
    func syncNow(completion: @escaping (Result<(pushed: Int, pulled: Int), Error>) -> Void) {
        queue.async {
            do {
                let result = try self.handle.syncNow()
                DispatchQueue.main.async { completion(.success((Int(result.pushed), Int(result.pulled)))) }
            } catch {
                DispatchQueue.main.async { completion(.failure(error)) }
            }
        }
    }

    /// Opens the near-real-time WebSocket connection. Call from
    /// scenePhase == .active; pair with stopLiveSync() on .background —
    /// holding a socket open while backgrounded doesn't work reliably (iOS
    /// suspends the app quickly), so background freshness comes from
    /// BackgroundSync's BGTaskScheduler job instead.
    func startLiveSync(onChanges: ((Int) -> Void)? = nil, onConnectionChange: ((Bool) -> Void)? = nil) {
        handle.startLiveSync(listener: SwiftLiveSyncListener(onChanges: onChanges, onConnectionChange: onConnectionChange))
    }

    func stopLiveSync() {
        handle.stopLiveSync()
    }

    private static func toFieldValue(_ v: Any?) -> FieldValue {
        switch v {
        case nil: return .null
        case let s as String: return .text(value: s)
        case let b as Bool: return .bool(value: b)
        case let n as NSNumber: return .number(value: n.doubleValue)
        default: return .text(value: String(describing: v))
        }
    }
}

/// Bridges the Rust `LiveSyncListener` callback interface to Swift closures.
private final class SwiftLiveSyncListener: LiveSyncListener {
    let onChanges: ((Int) -> Void)?
    let onConnectionChange: ((Bool) -> Void)?
    init(onChanges: ((Int) -> Void)?, onConnectionChange: ((Bool) -> Void)?) {
        self.onChanges = onChanges
        self.onConnectionChange = onConnectionChange
    }
    func onChangesApplied(count: UInt32) { DispatchQueue.main.async { self.onChanges?(Int(count)) } }
    func onConnectionState(connected: Bool) { DispatchQueue.main.async { self.onConnectionChange?(connected) } }
}

/// Background sync via BGTaskScheduler — this is what makes offline devices
/// catch up even while the app isn't open, subject to iOS's own scheduling
/// discretion (it decides *when* within your requested window, based on
/// battery, usage patterns, etc. — this is normal and expected, not a bug).
enum BackgroundSync {
    static let taskIdentifier = "com.yourapp.sync.refresh"

    /// Register once, in application(_:didFinishLaunchingWithOptions:) —
    /// must happen before the app finishes launching, per Apple's API rules.
    static func register(engineProvider: @escaping () -> SyncEngine?) {
        BGTaskScheduler.shared.register(forTaskWithIdentifier: taskIdentifier, using: nil) { task in
            handle(task: task as! BGAppRefreshTask, engineProvider: engineProvider)
        }
    }

    /// Call this each time the app enters background, to (re)schedule the
    /// next opportunistic run — iOS does not repeat tasks automatically.
    static func scheduleNext() {
        let request = BGAppRefreshTaskRequest(identifier: taskIdentifier)
        request.earliestBeginDate = Date(timeIntervalSinceNow: 15 * 60) // no earlier than 15 min out
        try? BGTaskScheduler.shared.submit(request)
    }

    private static func handle(task: BGAppRefreshTask, engineProvider: @escaping () -> SyncEngine?) {
        scheduleNext() // always reschedule the next one before this one finishes

        guard let engine = engineProvider() else {
            task.setTaskCompleted(success: false)
            return
        }

        task.expirationHandler = {
            // iOS is revoking our time — nothing more to do; syncNow() will
            // simply not have completed, and the outbox/cursor state is
            // safe to resume from on the next attempt (idempotent by design).
        }

        engine.syncNow { result in
            task.setTaskCompleted(success: (try? result.get()) != nil)
        }
    }
}

/*
Example usage:

let sync = try SyncEngine(serverUrl: "https://api.example.com", authToken: token,
                           deviceId: UIDevice.current.identifierForVendor!.uuidString,
                           userId: currentUserId)

sync.upsert(table: "tasks", rowId: taskId, fields: ["title": "Buy milk", "done": false], isInsert: true) { _ in }

// In your App/SceneDelegate:
//   .onChange(of: scenePhase) { phase in
//       if phase == .active { sync.startLiveSync(onChanges: { _ in refreshUI() }) }
//       if phase == .background { sync.stopLiveSync(); BackgroundSync.scheduleNext() }
//   }
// In didFinishLaunchingWithOptions:
//   BackgroundSync.register(engineProvider: { AppState.shared.syncEngine })
// In Info.plist, add "com.yourapp.sync.refresh" under
// BGTaskSchedulerPermittedIdentifiers, and enable the "Background fetch"
// capability.
*/
